python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/codegen/lower_inst.rs'
s = open(p).read()
old = '''    let ptr_reg = abi::symbol_scratch_reg(ctx.emitter);
    let addr_reg = abi::secondary_scratch_reg(ctx.emitter);
    abi::emit_symbol_address(ctx.emitter, ptr_reg, &label);
    abi::emit_store_reg_to_symbol(ctx.emitter, ptr_reg, "_rt_diag_loc_ptr", 0);
    abi::emit_load_int_immediate(ctx.emitter, addr_reg, len as i64);
    abi::emit_store_reg_to_symbol(ctx.emitter, addr_reg, "_rt_diag_loc_len", 0);'''
new = '''    // NOT the primary scratch: `emit_store_reg_to_symbol` borrows that one to materialize the
    // symbol's own address, so handing it the value to store overwrites the value first.
    let ptr_reg = abi::secondary_scratch_reg(ctx.emitter);
    let len_reg = abi::tertiary_scratch_reg(ctx.emitter);
    abi::emit_symbol_address(ctx.emitter, ptr_reg, &label);
    abi::emit_store_reg_to_symbol(ctx.emitter, ptr_reg, "_rt_diag_loc_ptr", 0);
    abi::emit_load_int_immediate(ctx.emitter, len_reg, len as i64);
    abi::emit_store_reg_to_symbol(ctx.emitter, len_reg, "_rt_diag_loc_len", 0);'''
assert old in s, "publish anchor not found"
s = s.replace(old, new, 1)
open(p, 'w').write(s)
print("scratch registers corrected")
